input.diff:
--- a/rtl/fsm_controller.v
+++ b/rtl/fsm_controller.v
@@ -52,7 +52,7 @@ module fsm_controller #(

                 S_MAIN_YELLOW: begin
                     if (timer_cnt == TICKS_YELLOW - 1'b1) begin
-                        current_state <= S_SIDE_YELLOW;
+                        current_state <= S_SIDE_GREEN;
                         timer_cnt     <= 4'd0;
                     end else begin
                         timer_cnt <= timer_cnt + 1'b1;

